  ui_story_32280401_19_dialog_content = "And just recently, I confirmed the location of <color=#FFB400>that place</color>! Wanna come find it with me?",
  ui_story_32280401_20_option_content = "Let's go!",
  ui_story_32280401_21_dialog_content = "I can't say I'm not interested in learning the secret recipe for this awesome candy.",
