  ui_story_32280401_23_option_content = "Well...",
  ui_story_32280401_24_dialog_content = "Do we really have to go on an adventure just for some candy?",
  ui_story_32280401_25_dialog_content = "You know you just ate my very last Lemon Supreme, right? I'm not about to let you walk away after that!",
