  ui_story_32280401_27_dialog_content = "Fine...",
  ui_story_32280401_28_dialog_content = "There's no time to lose! Let's move out!",
  ui_story_32280401_29_dialog_content = "<color=#e8d9bb>Some time later</color>",
  ui_story_32280401_30_dialog_content = "So this is where the secret recipe is hidden?",
  ui_story_32280401_31_dialog_content = "It's just a normal-looking forest. This is a lot different from what I imagined.",
  ui_story_32280401_32_dialog_content = "A true warrior doesn't judge the enemy solely on appearances.",
