  ui_story_32280401_92_dialog_content = "<color=#e8d9bb>Zeta angrily kicks the chest and pulls out one of her candy-filled robots.</color>",
  ui_story_32280401_93_dialog_content = "Calm down, Zeta!",
  ui_story_32280401_94_dialog_content = "I hope you're watching, you crooked queen! This is what happens when you mess with a warrior!",
  ui_story_32280401_95_dialog_content = "Hang on, Zeta... Take a closer look! There's a false bottom in the chest!",
  ui_story_32280401_96_dialog_content = "A false bottom? Hey, you're right! If I hadn't kicked the chest just now, we never would've noticed it!",
  ui_story_32280401_97_dialog_content = "... Does that mean the note we found earlier was just a diversion?",
  ui_story_32280401_98_dialog_content = "I see! So that's how Queen Kandi prevents evildoers from getting ahold of her recipe.",
  ui_story_32280401_99_dialog_content = "This has to be fate!",
