  ui_story_32280401_101_dialog_content = "It has to be the actual recipe for the <color=#FFB400>Lemon Supreme</color>, right?",
  ui_story_32280401_102_dialog_content = "\"If you are reading this, it means you have destroyed my chest out of pure anger.\"",
  ui_story_32280401_103_dialog_content = "\"They say sweetness is best appreciated when paired with an opposing flavor, and few things make treats sweeter than another person's suffering.\"",
