  ui_story_32280401_119_dialog_content = "S-So that's what it is! I finally get it now!",
  ui_story_32280401_120_dialog_content = "\"They say sweetness is best appreciated when paired with an opposing flavor\"!",
  ui_story_32280401_121_dialog_content = "The salt from this cave is the secret behind the <color=#FFB400>Lemon Supreme's</color> sweet and refreshing taste!",
  ui_story_32280401_122_dialog_content = "So all this time, Queen Kandi—",
  ui_story_32280401_123_dialog_content = "Yep! She was never hiding the recipe for the <color=#FFB400>Lemon Supreme</color> to begin with! That's because it's right here in this place!",
